import{_ as n,c as s,o as p,al as e}from"./chunks/framework.QMC68jD7.js";const u=JSON.parse('{"title":"1.去掉原生导航栏","description":"","frontmatter":{},"headers":[],"relativePath":"tech/小程序/19.自定义导航栏.md","filePath":"tech/小程序/19.自定义导航栏.md","lastUpdated":1777271852000}'),l={name:"tech/小程序/19.自定义导航栏.md"};function i(t,a,r,c,o,m){return p(),s("div",null,[...a[0]||(a[0]=[e(`<p>了解更多参考网址：<a href="https://blog.csdn.net/little_shallot/article/details/110205652" target="_blank" rel="noreferrer">https://blog.csdn.net/little_shallot/article/details/110205652</a></p><h1 id="_1-去掉原生导航栏" tabindex="-1">1.去掉原生导航栏 <a class="header-anchor" href="#_1-去掉原生导航栏" aria-label="Permalink to &quot;1.去掉原生导航栏&quot;">​</a></h1><p>json文件里面加入&quot;navigationStyle&quot;:&quot;custom&quot;即可去掉原生导航栏<br>既可在app.json中去掉，也可以在页面中json去掉</p><h1 id="_2-获取导航栏高度" tabindex="-1">2.获取导航栏高度 <a class="header-anchor" href="#_2-获取导航栏高度" aria-label="Permalink to &quot;2.获取导航栏高度&quot;">​</a></h1><p>用固定高度加定位，发现在不同设备下尺寸不对，就比如iPhone X那个刘海屏<br>![](<a href="https://cdn.nlark.com/yuque/0/2022/png/22278242/1671460149976-2795ffdb-3e9d-4420-811a-ea19f84d5f0f.png#averageHue=%23f8f8f8%5C&amp;clientId=u84799904-4692-4%5C&amp;crop=0%5C&amp;crop=0%5C&amp;crop=1%5C&amp;crop=1%5C&amp;from=paste%5C&amp;id=u4012a567%5C&amp;margin=%5C" target="_blank" rel="noreferrer">https://cdn.nlark.com/yuque/0/2022/png/22278242/1671460149976-2795ffdb-3e9d-4420-811a-ea19f84d5f0f.png#averageHue=%23f8f8f8\\&amp;clientId=u84799904-4692-4\\&amp;crop=0\\&amp;crop=0\\&amp;crop=1\\&amp;crop=1\\&amp;from=paste\\&amp;id=u4012a567\\&amp;margin=\\</a>[object Object]&amp;originHeight=336&amp;originWidth=1011&amp;originalType=url&amp;ratio=1&amp;rotation=0&amp;showTitle=false&amp;status=done&amp;style=none&amp;taskId=u7a342f1d-49ed-4270-a9a5-6dd4b058965&amp;title=#averageHue=%23f8f8f8&amp;from=url&amp;id=tz8so&amp;originHeight=336&amp;originWidth=1011&amp;originalType=binary&amp;ratio=1.75&amp;rotation=0&amp;showTitle=false&amp;status=done&amp;style=none&amp;title=)<br>![](<a href="https://cdn.nlark.com/yuque/0/2022/png/22278242/1671460149855-4239eacf-1719-4669-bbb3-c96322c2b934.png#averageHue=%23e3e3e3%5C&amp;clientId=u84799904-4692-4%5C&amp;crop=0%5C&amp;crop=0%5C&amp;crop=1%5C&amp;crop=1%5C&amp;from=paste%5C&amp;id=ua397ae93%5C&amp;margin=%5C" target="_blank" rel="noreferrer">https://cdn.nlark.com/yuque/0/2022/png/22278242/1671460149855-4239eacf-1719-4669-bbb3-c96322c2b934.png#averageHue=%23e3e3e3\\&amp;clientId=u84799904-4692-4\\&amp;crop=0\\&amp;crop=0\\&amp;crop=1\\&amp;crop=1\\&amp;from=paste\\&amp;id=ua397ae93\\&amp;margin=\\</a>[object Object]&amp;originHeight=406&amp;originWidth=1099&amp;originalType=url&amp;ratio=1&amp;rotation=0&amp;showTitle=false&amp;status=done&amp;style=none&amp;taskId=u3d28bb9f-b88e-4a1f-9c10-b35f3d17003&amp;title=#averageHue=%23e3e3e3&amp;from=url&amp;id=B8Cx5&amp;originHeight=406&amp;originWidth=1099&amp;originalType=binary&amp;ratio=1.75&amp;rotation=0&amp;showTitle=false&amp;status=done&amp;style=none&amp;title=)</p><h4 id="wx-getmenubuttonboundingclientrect" tabindex="-1">wx.getMenuButtonBoundingClientRect() <a class="header-anchor" href="#wx-getmenubuttonboundingclientrect" aria-label="Permalink to &quot;wx.getMenuButtonBoundingClientRect()&quot;">​</a></h4><p>获取菜单按钮（右上角胶囊按钮）的布局位置信息。坐标信息以屏幕左上角为原点。获取值的单位为px，所以设置的时候也需要使用px进行设置<br>bottom: 56 屏幕顶部到按钮底部之间的距离<br>height: 32 按钮高度<br>left: 226 屏幕左边到按钮左侧之间的距离<br>right: 313 屏幕左边到按钮右侧之间的距离<br>top: 24 屏幕顶部到按钮顶部之间的距离<br>width: 87 胶囊按钮宽度<br>但是切换到不同尺寸的屏幕，获取到的菜单按钮的数据是不一样的，特别是top值，所以，当我们想要添加一个跟胶囊按钮同位置的input框的时候，可以通过getMenuButtonBoundingClientRect获取距离顶部的高度，再将值设置给input框<br><img src="https://cdn.nlark.com/yuque/0/2023/png/8438658/1692538571150-22d6390a-16bd-4064-85c6-b80e3911a296.png#averageHue=%23738ed7&amp;clientId=u59afb8a0-aa90-4&amp;from=paste&amp;height=208&amp;id=u9e2b9b58&amp;originHeight=364&amp;originWidth=664&amp;originalType=binary&amp;ratio=1.75&amp;rotation=0&amp;showTitle=false&amp;size=307905&amp;status=done&amp;style=none&amp;taskId=ue7039eae-b6b0-4c60-9088-64c89992f55&amp;title=&amp;width=379.42857142857144" alt="image_XiyZm43fXt.png"><br>json配置</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;usingComponents&quot;: {},</span></span>
<span class="line"><span>  &quot;navigationBarTitleText&quot;: &quot;购物车&quot;,</span></span>
<span class="line"><span>  &quot;navigationStyle&quot;: &quot;custom&quot;,</span></span>
<span class="line"><span>  &quot;navigationBarTextStyle&quot;: &quot;white&quot;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>wxml</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;view class=&quot;search&quot; style=&quot;height:{{num2}}px; top: {{num1}}px;&quot;&gt;</span></span>
<span class="line"><span>    &lt;input type=&quot;text&quot; class=&quot;inp&quot; placeholder=&quot;郑州耀莱成龙影城&quot; placeholder-class=&quot;pinput&quot;/&gt;</span></span>
<span class="line"><span>&lt;/view&gt;</span></span>
<span class="line"><span>&lt;view class=&quot;banner&quot;&gt;</span></span>
<span class="line"><span>    &lt;image class=&quot;img&quot; src=&quot;/file/banner.jpeg&quot;&gt;&lt;/image&gt;</span></span>
<span class="line"><span>&lt;/view&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>wxss</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/* pages/shopcar/shopcar.wxss */</span></span>
<span class="line"><span>.search{</span></span>
<span class="line"><span>  height: 90rpx;</span></span>
<span class="line"><span>  position: absolute;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>.inp{</span></span>
<span class="line"><span>  width: 400rpx;</span></span>
<span class="line"><span>  height: 32px;</span></span>
<span class="line"><span>  border-radius: 40rpx;</span></span>
<span class="line"><span>  margin-left: 20rpx;</span></span>
<span class="line"><span>  padding-left: 20rpx;</span></span>
<span class="line"><span>  background-color: rgba(255, 255, 255, 0.6);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>/* 设置placeholder的样式 */</span></span>
<span class="line"><span>.pinput{</span></span>
<span class="line"><span>  color: #000;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>.banner{</span></span>
<span class="line"><span>  height: 400rpx;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>.img{</span></span>
<span class="line"><span>  height: 100%;</span></span>
<span class="line"><span>  width: 100%;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br></div></div><p>js</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Page({</span></span>
<span class="line"><span>  /**</span></span>
<span class="line"><span>   * 页面的初始数据</span></span>
<span class="line"><span>   */</span></span>
<span class="line"><span>  data: {</span></span>
<span class="line"><span>    // 距离顶部的高度</span></span>
<span class="line"><span>    num1:0,</span></span>
<span class="line"><span>    // 胶囊的高度</span></span>
<span class="line"><span>    num2:0</span></span>
<span class="line"><span>  },</span></span>
<span class="line"><span>  onLoad(options) {</span></span>
<span class="line"><span>    let that = this;</span></span>
<span class="line"><span>    //获取胶囊信息</span></span>
<span class="line"><span>    let obj = wx.getMenuButtonBoundingClientRect();</span></span>
<span class="line"><span>    this.setData({</span></span>
<span class="line"><span>      num1:obj.top,</span></span>
<span class="line"><span>      num2:obj.height</span></span>
<span class="line"><span>    })</span></span>
<span class="line"><span>    console.log(obj);</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>})</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br></div></div><p>效果<br><img src="https://cdn.nlark.com/yuque/0/2023/png/8438658/1692538562461-4160e27c-db40-408e-b395-8dcf2bfcfd95.png#averageHue=%23738ed7&amp;clientId=u59afb8a0-aa90-4&amp;from=paste&amp;height=208&amp;id=u40f5197f&amp;originHeight=364&amp;originWidth=664&amp;originalType=binary&amp;ratio=1.75&amp;rotation=0&amp;showTitle=false&amp;size=307905&amp;status=done&amp;style=none&amp;taskId=uceaf4b67-465a-4c4a-94c4-9fc6e586774&amp;title=&amp;width=379.42857142857144" alt="image_XiyZm43fXt.png"><img src="https://cdn.nlark.com/yuque/0/2023/png/8438658/1692538530386-268537e9-c424-48c3-980c-13d554b3dfdd.png#averageHue=%234b94ea&amp;clientId=u59afb8a0-aa90-4&amp;from=paste&amp;height=177&amp;id=P29bI&amp;originHeight=310&amp;originWidth=578&amp;originalType=binary&amp;ratio=1.75&amp;rotation=0&amp;showTitle=false&amp;size=234106&amp;status=done&amp;style=none&amp;taskId=u115e9a0f-a9b6-48de-8b1c-077c2a77261&amp;title=&amp;width=330.2857142857143" alt="image_gh9OTtvP_0.png"></p>`,15)])])}const d=n(l,[["render",i]]);export{u as __pageData,d as default};
